package com.bookmyturf.app;

import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.bookmyturf.app.data.*;
import java.util.*;

/** Java/XML migration demo. Data is intentionally in-memory; backend features need re-integration. */
public class MainActivity extends AppCompatActivity {
 private LinearLayout nav; private FrameLayout container;
 private final List<Turf> turfs=new ArrayList<>(); private final List<Tournament> tournaments=new ArrayList<>(); private final List<Booking> bookings=new ArrayList<>();
 private final Set<String> favorites=new HashSet<>(), slots=new LinkedHashSet<>(); private Turf selected; private String query="";
 private final int bg=0xFF101018,card=0xFF1B1B28,purple=0xFF6B4EFF,white=0xFFF7F7FB,muted=0xFFB5B5C5,green=0xFF15B981;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);container=findViewById(R.id.screenContainer);nav=findViewById(R.id.bottomNavigation);seed();screen("Welcome");}
 private void seed(){
  turfs.add(new Turf("1","Strike Arena","Gotri, Vadodara","Football, Cricket",1200,4.5,"Outdoor turf with changing rooms and floodlights."));
  turfs.add(new Turf("2","TurfX Sports Arena","Akota, Vadodara","Cricket, Football",1500,4.4,"Sports arena for group games and tournaments."));
  turfs.add(new Turf("3","PlayZone","Vasna Road, Vadodara","Badminton, Football",900,4.2,"Compact sports venue for friends and teams."));
  tournaments.add(new Tournament("Vadodara Football Cup","Football","Strike Arena, Gotri","8 Oct 2026",6,16,1200,25000));
  tournaments.add(new Tournament("Box Cricket Clash","Cricket","TurfX Sports Arena, Akota","15 Oct 2026",7,20,1500,35000));
  tournaments.add(new Tournament("Badminton Doubles Open","Badminton","PlayZone, Vadodara","22 Oct 2026",2,24,500,10000));
 }
 private void screen(String name){
  container.removeAllViews(); ScrollView sc=new ScrollView(this); LinearLayout p=new LinearLayout(this);p.setOrientation(1);p.setPadding(d(18),d(18),d(18),d(22));p.setBackgroundColor(bg);sc.addView(p);container.addView(sc);
  if(name.equals("Welcome")){TextView logo=txt("BOOKMYTURF",30,white,true);logo.setGravity(Gravity.CENTER);p.addView(logo,lp());TextView tag=txt("LESS PLANNING. MORE PLAY.",13,muted,true);tag.setGravity(Gravity.CENTER);p.addView(tag,lp());gap(p,40);btn(p,"Explore turfs",()->screen("Home"),purple);btn(p,"Continue as demo user",()->screen("Home"),card);p.addView(txt("Java + XML migration demo",12,muted,false),lp());nav.setVisibility(View.GONE);return;}
  nav.setVisibility(View.VISIBLE);p.addView(txt(name,26,white,true),lp());p.addView(txt("Discover • Play • Compete",13,muted,false),lp());gap(p,12);
  switch(name){case "Home":home(p);break;case "Explore":explore(p);break;case "Details":details(p);break;case "Slots":slotScreen(p);break;case "Summary":summary(p);break;case "Payment":payment(p);break;case "Confirmation":confirmation(p);break;case "Bookings":bookingScreen(p);break;case "Tournaments":tournamentScreen(p);break;case "Favorites":favoritesScreen(p);break;case "Profile":profile(p);break;case "Admin":admin(p);break;default:home(p);}
  nav.removeAllViews();for(String label:new String[]{"Home","Explore","Tournaments","Bookings","Profile"}){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(10);b.setTextColor(white);b.setBackgroundColor(0x00101018);nav.addView(b,new LinearLayout.LayoutParams(0,-1,1));b.setOnClickListener(v->screen(label));}
 }
 private void home(LinearLayout p){p.addView(txt("Playing near • Vadodara",15,white,true),lp());EditText e=new EditText(this);e.setSingleLine();e.setHint("Search turfs and tournaments");e.setTextColor(white);e.setHintTextColor(muted);e.setBackgroundColor(card);p.addView(e,new LinearLayout.LayoutParams(-1,d(48)));btn(p,"Search",()->{query=e.getText().toString();screen("Explore");},purple);gap(p,10);p.addView(txt("Explore sports",19,white,true),lp());for(String s:new String[]{"Football","Cricket","Badminton"})btn(p,s,()->{query=s;screen("Explore");},card);p.addView(txt("Featured tournaments",19,white,true),lp());for(Tournament t:tournaments)tournamentCard(p,t);btn(p,"Browse turfs",()->screen("Explore"),purple);}
 private void explore(LinearLayout p){EditText e=new EditText(this);e.setSingleLine();e.setText(query);e.setHint("Search turf, area or sport");e.setTextColor(white);e.setHintTextColor(muted);e.setBackgroundColor(card);p.addView(e,new LinearLayout.LayoutParams(-1,d(48)));btn(p,"Apply search",()->{query=e.getText().toString().trim();screen("Explore");},purple);boolean any=false;for(Turf t:turfs){String q=query.toLowerCase(Locale.ROOT);if(q.isEmpty()||t.name.toLowerCase(Locale.ROOT).contains(q)||t.area.toLowerCase(Locale.ROOT).contains(q)||t.sports.toLowerCase(Locale.ROOT).contains(q)){turfCard(p,t);any=true;}}if(!any)p.addView(txt("No turfs found. Try another search.",14,muted,false),lp());btn(p,"Clear search",()->{query="";screen("Explore");},card);}
 private void turfCard(LinearLayout p,Turf t){LinearLayout c=card(p);c.addView(txt(t.name,18,white,true),lp());c.addView(txt(t.area+" • "+t.sports,13,muted,false),lp());c.addView(txt("★ "+t.rating+" • ₹"+t.pricePerHour+"/hour",14,green,true),lp());btn(c,"View details",()->{selected=t;screen("Details");},purple);}
 private void details(LinearLayout p){if(selected==null){screen("Explore");return;}p.addView(txt(selected.name,23,white,true),lp());p.addView(txt(selected.area,14,muted,false),lp());p.addView(txt(selected.description,14,white,false),lp());p.addView(txt(selected.sports+" • ★ "+selected.rating,15,green,true),lp());btn(p,favorites.contains(selected.id)?"Remove favorite":"Save turf",()->{if(!favorites.add(selected.id))favorites.remove(selected.id);screen("Details");},card);btn(p,"Choose time slots",()->{slots.clear();screen("Slots");},purple);}
 private void slotScreen(LinearLayout p){if(selected==null){screen("Explore");return;}p.addView(txt("Demo date: today • Choose hourly slots",14,muted,false),lp());for(String s:new String[]{"08:00–09:00","09:00–10:00","10:00–11:00","11:00–12:00","17:00–18:00","18:00–19:00"})btn(p,(slots.contains(s)?"✓ ":"+ ")+s+" • ₹"+selected.pricePerHour,()->{if(slots.contains(s))slots.remove(s);else if(slots.size()<3)slots.add(s);else Toast.makeText(this,"Maximum three demo slots",Toast.LENGTH_SHORT).show();screen("Slots");},slots.contains(s)?purple:card);btn(p,"Continue to summary",()->{if(slots.isEmpty())Toast.makeText(this,"Select a slot first",Toast.LENGTH_SHORT).show();else screen("Summary");},green);}
 private int turfFee(){return selected==null?0:selected.pricePerHour*slots.size();}
 private void summary(LinearLayout p){if(selected==null||slots.isEmpty()){screen("Explore");return;}int fee=turfFee(),platform=20;double gst=(fee+platform)*.18;p.addView(txt(selected.name,19,white,true),lp());p.addView(txt("Slots: "+String.join(", ",slots),13,muted,false),lp());p.addView(txt("Turf fee: ₹"+fee,15,white,false),lp());p.addView(txt("Platform fee: ₹20",15,white,false),lp());p.addView(txt(String.format(Locale.US,"GST (18%%): ₹%.2f",gst),15,white,false),lp());p.addView(txt(String.format(Locale.US,"Total: ₹%.2f",fee+platform+gst),22,green,true),lp());btn(p,"Continue to demo payment",()->screen("Payment"),purple);}
 private void payment(LinearLayout p){p.addView(txt("Demo checkout — no real money is charged.",15,muted,false),lp());btn(p,"Simulate successful payment",()->{bookings.add(0,new Booking("BMT-DEMO-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT),selected==null?"Unknown":selected.name,String.join(", ",slots),turfFee()+20,"CONFIRMED"));screen("Confirmation");},green);btn(p,"Cancel",()->screen("Summary"),card);}
 private void confirmation(LinearLayout p){p.addView(txt("Booking confirmed (demo)",22,green,true),lp());if(!bookings.isEmpty())p.addView(txt(bookings.get(0).id,14,white,false),lp());btn(p,"View bookings",()->screen("Bookings"),purple);btn(p,"Home",()->screen("Home"),card);}
 private void bookingScreen(LinearLayout p){if(bookings.isEmpty()){p.addView(txt("No bookings in this app session yet.",15,muted,false),lp());return;}for(Booking b:bookings){LinearLayout c=card(p);c.addView(txt(b.turfName,17,white,true),lp());c.addView(txt(b.id,12,muted,false),lp());c.addView(txt(b.slots+" • ₹"+b.amount+" • "+b.status,14,green,false),lp());}}
 private void tournamentScreen(LinearLayout p){for(Tournament t:tournaments)tournamentCard(p,t);}
 private void tournamentCard(LinearLayout p,Tournament t){LinearLayout c=card(p);c.addView(txt(t.name,17,white,true),lp());c.addView(txt(t.sport+" • "+t.venue+" • "+t.date,13,muted,false),lp());c.addView(txt(t.playersPerTeam+" players/team • up to "+t.maxTeams+" teams",13,muted,false),lp());c.addView(txt("Prize ₹"+t.prizePool+" • Entry ₹"+t.entryFee+" (demo)",14,green,true),lp());}
 private void favoritesScreen(LinearLayout p){boolean any=false;for(Turf t:turfs)if(favorites.contains(t.id)){turfCard(p,t);any=true;}if(!any)p.addView(txt("No saved turfs yet.",14,muted,false),lp());}
 private void profile(LinearLayout p){p.addView(txt("Demo User",20,white,true),lp());for(String s:new String[]{"Bookings","Favorites","Tournaments","Admin"})btn(p,s,()->screen(s),card);btn(p,"Log out",()->screen("Welcome"),purple);}
 private void admin(LinearLayout p){p.addView(txt("Local demo tools; cloud admin is not connected.",14,muted,false),lp());btn(p,"Turf inventory",()->screen("Explore"),card);btn(p,"Tournaments",()->screen("Tournaments"),card);btn(p,"Bookings",()->screen("Bookings"),card);btn(p,"Add demo turf",()->{turfs.add(new Turf("t"+(turfs.size()+1),"New Demo Turf","Vadodara","Football, Cricket",1000,4.0,"Locally added demo venue."));Toast.makeText(this,"Added in memory only",Toast.LENGTH_SHORT).show();screen("Admin");},purple);}
 private LinearLayout card(LinearLayout p){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(d(14),d(12),d(14),d(12));c.setBackgroundColor(card);LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-1,-2);x.bottomMargin=d(12);p.addView(c,x);return c;}
 private void btn(LinearLayout p,String s,Runnable r,int color){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(white);b.setTextSize(13);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color));LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-1,d(48));x.topMargin=d(5);x.bottomMargin=d(4);p.addView(b,x);b.setOnClickListener(v->r.run());}
 private TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);t.setPadding(0,d(3),0,d(3));return t;}
 private LinearLayout.LayoutParams lp(){return new LinearLayout.LayoutParams(-1,-2);}private void gap(LinearLayout p,int h){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,d(h)));}private int d(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
}
